-- Binds mirror ~/.config/niri/config.kdl (niri "Mod" = Alt).
-- Column operations rely on the scrolling layout (general.layout above).
local mainMod = "ALT"
local superMod = "SUPER"

local function bind(keys, dispatcher, opts)
    hl.bind(mainMod .. " + " .. keys, dispatcher, opts)
end

-- Apps / session
bind("D",              hl.dsp.exec_cmd("dms ipc call spotlight toggle"))
bind("F2",             hl.dsp.exec_cmd("dms ipc call spotlight toggle"))
bind("SHIFT + RETURN", hl.dsp.exec_cmd(terminal))
bind("O",              hl.dsp.exec_cmd("dms ipc call hypr toggleOverview"))
hl.bind(superMod .. " + L",           hl.dsp.exec_cmd("dms ipc call lock lock"))
hl.bind(superMod .. " + ALT + S",     hl.dsp.exec_cmd("pkill orca || exec orca"), { locked = true })
bind("CTRL + minus",   hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
-- DPMS from a bind directly is discouraged by the wiki; defer it with a timer
bind("SHIFT + P", function()
    hl.timer(function()
        hl.dispatch(hl.dsp.dpms({ action = "disable" }))
    end, { timeout = 500, type = "oneshot" })
end)

-- Close window
bind("F4",        hl.dsp.window.close())
bind("SHIFT + C", hl.dsp.window.close())

-- Focus columns / windows
bind("left",  hl.dsp.focus({ direction = "l" }))
bind("right", hl.dsp.focus({ direction = "r" }))
bind("up",    hl.dsp.focus({ direction = "u" }))
bind("down",  hl.dsp.focus({ direction = "d" }))
bind("H",     hl.dsp.focus({ direction = "l" }))
bind("L",     hl.dsp.focus({ direction = "r" }))
bind("K",     hl.dsp.focus({ direction = "u" }))
bind("J",     hl.dsp.focus({ direction = "d" }))

-- Move columns / windows
bind("SHIFT + left",  hl.dsp.layout("swapcol l"))
bind("SHIFT + right", hl.dsp.layout("swapcol r"))
bind("SHIFT + up",    hl.dsp.window.move({ direction = "u" }))
bind("SHIFT + down",  hl.dsp.window.move({ direction = "d" }))
bind("CTRL + H",      hl.dsp.layout("swapcol l"))
bind("CTRL + L",      hl.dsp.layout("swapcol r"))
bind("CTRL + K",      hl.dsp.window.move({ direction = "u" }))
bind("CTRL + J",      hl.dsp.window.move({ direction = "d" }))

-- Monitors
bind("Q",         hl.dsp.focus({ monitor = "l" }))
bind("E",         hl.dsp.focus({ monitor = "r" }))
bind("SHIFT + H", hl.dsp.focus({ monitor = "l" }))
bind("SHIFT + L", hl.dsp.focus({ monitor = "r" }))
bind("SHIFT + K", hl.dsp.focus({ monitor = "u" }))
bind("SHIFT + J", hl.dsp.focus({ monitor = "d" }))

bind("SHIFT + Q",        hl.dsp.window.move({ monitor = "l" }))
bind("SHIFT + E",        hl.dsp.window.move({ monitor = "r" }))
bind("SHIFT + CTRL + H", hl.dsp.window.move({ monitor = "l" }))
bind("SHIFT + CTRL + L", hl.dsp.window.move({ monitor = "r" }))
bind("SHIFT + CTRL + K", hl.dsp.window.move({ monitor = "u" }))
bind("SHIFT + CTRL + J", hl.dsp.window.move({ monitor = "d" }))
bind("SHIFT + CTRL + up",   hl.dsp.window.move({ monitor = "u" }))
bind("SHIFT + CTRL + down", hl.dsp.window.move({ monitor = "d" }))

bind("SHIFT + CTRL + left",  hl.dsp.workspace.move({ monitor = "l" }))
bind("SHIFT + CTRL + right", hl.dsp.workspace.move({ monitor = "r" }))

-- Workspaces up/down (per monitor, including the next empty one like niri)
bind("Page_Down",        hl.dsp.focus({ workspace = "r+1" }))
bind("Page_Up",          hl.dsp.focus({ workspace = "r-1" }))
bind("U",                hl.dsp.focus({ workspace = "r+1" }))
bind("I",                hl.dsp.focus({ workspace = "r-1" }))
bind("CTRL + Page_Down", hl.dsp.window.move({ workspace = "r+1" }))
bind("CTRL + Page_Up",   hl.dsp.window.move({ workspace = "r-1" }))
bind("SHIFT + U",        hl.dsp.window.move({ workspace = "r+1" }))
bind("SHIFT + I",        hl.dsp.window.move({ workspace = "r-1" }))

bind("mouse_down",              hl.dsp.focus({ workspace = "r+1" }))
bind("mouse_up",                hl.dsp.focus({ workspace = "r-1" }))
bind("CTRL + mouse_down",       hl.dsp.window.move({ workspace = "r+1" }))
bind("CTRL + mouse_up",         hl.dsp.window.move({ workspace = "r-1" }))
bind("SHIFT + mouse_down",      hl.dsp.focus({ direction = "r" }))
bind("SHIFT + mouse_up",        hl.dsp.focus({ direction = "l" }))
bind("CTRL + SHIFT + mouse_down", hl.dsp.layout("swapcol r"))
bind("CTRL + SHIFT + mouse_up",   hl.dsp.layout("swapcol l"))

-- Mod+[1-9] focuses a workspace, Mod+Ctrl+[1-9] moves the window there
for i = 1, 9 do
    bind(tostring(i),          hl.dsp.focus({ workspace = i }))
    bind("CTRL + " .. i,       hl.dsp.window.move({ workspace = i }))
end

-- Column composition
bind("bracketleft",  hl.dsp.layout("consume_or_expel prev"))
bind("bracketright", hl.dsp.layout("consume_or_expel next"))
bind("comma",        hl.dsp.layout("consume"))
bind("period",       hl.dsp.layout("expel"))

-- Sizing
bind("R",             hl.dsp.layout("colresize +conf"))
bind("SHIFT + R",     hl.dsp.layout("colresize -conf"))
bind("A",             hl.dsp.layout("colresize 1.0"))
bind("CTRL + F",      hl.dsp.layout("fit expand"))
bind("C",             hl.dsp.layout("fit_into_view"))
bind("CTRL + C",      hl.dsp.layout("fit visible"))
bind("minus",         hl.dsp.layout("colresize -0.1"))
bind("equal",         hl.dsp.layout("colresize +0.1"))
bind("SHIFT + minus", hl.dsp.window.resize({ x = 0, y = -100, relative = true }))
bind("SHIFT + equal", hl.dsp.window.resize({ x = 0, y = 100, relative = true }))
bind("SHIFT + F",     hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
bind("M",             hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))

-- Floating / tabs
bind("V", hl.dsp.window.float({ action = "toggle" }))
bind("SHIFT + V", function()
    local w = hl.get_active_window()
    if w and w.floating then
        hl.dispatch(hl.dsp.window.cycle_next({ tiled = true }))
    else
        hl.dispatch(hl.dsp.window.cycle_next({ floating = true }))
    end
end)
bind("W", hl.dsp.group.toggle())

-- Screenshots
hl.bind("Print",              hl.dsp.exec_cmd("dms screenshot region"))
hl.bind("CTRL + Print",       hl.dsp.exec_cmd("dms screenshot full"))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("dms screenshot window"))

-- Move/resize windows with mainMod + LMB/RMB and dragging
bind("mouse:272", hl.dsp.window.drag(),   { mouse = true })
bind("mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Media keys (allowed while locked, as in niri)
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 0.1+ -l 1.0"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 0.1-"),        { locked = true, repeating = true })
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),        { locked = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),      { locked = true })
hl.bind("XF86AudioPlay",         hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioStop",         hl.dsp.exec_cmd("playerctl stop"),       { locked = true })
hl.bind("XF86AudioPrev",         hl.dsp.exec_cmd("playerctl previous"),   { locked = true })
hl.bind("XF86AudioNext",         hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl --class=backlight set +10%"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl --class=backlight set 10%-"), { locked = true, repeating = true })


