---------------------------------
---- NAMED WORKSPACES (niri) ----
---------------------------------

-- Mirrors the named workspaces / open-on-workspace rules in ~/.config/niri/config.kdl
-- Workspaces with an id are regular numbered workspaces (so r+1/r-1 and Mod+N reach them)
-- labelled with default_name; the rest are pure named workspaces.
local namedWorkspaces = {
    { name = "web",   monitor = "HDMI-A-1", id = 1 },
    { name = "code",  monitor = "HDMI-A-1", id = 2 },
    { name = "docs",  monitor = "HDMI-A-1", id = 3 },
    { name = "chats", monitor = "eDP-1", id = 8 },
    { name = "media", monitor = "eDP-1", id = 9 },
}

local workspaceSelector = {}
for _, ws in ipairs(namedWorkspaces) do
    local selector = ws.id and tostring(ws.id) or ("name:" .. ws.name)
    workspaceSelector[ws.name] = selector
    hl.workspace_rule({
        workspace    = selector,
        default_name = ws.id and ws.name or nil,
        monitor      = ws.monitor,
        persistent   = true,
    })
end

local workspaceApps = {
    web = {
        "^chromium-browser-beta$",
        "^firefox$",
        "^librewolf$",
    },
    chats = {
        "^org\\.telegram\\.desktop$",
        "^com\\.slack\\.Slack$",
        "^org\\.kde\\.kmail2$",
        "^thunderbird$",
        "^max$",
        "^org\\.squidowl\\.halloy$",
        "^discord$",
        "^org\\.kde\\.kontact$",
        "com.rtosta.zapzap",
    },
    media = {
        "^org\\.kde\\.kasts$",
        "^vlc$",
        "^org\\.kde\\.ktorrent$",
        "org.kde.elisa",
    },
    code = {
        "^com.anthropic.Claude$",
        "^chatgpt$",
        "^dev.zed.Zed$",
    },
    docs = {
        "^obsidian$",
        "^md.Obsidian$",
        "md.obsidian.Obsidian",
    },
}

for ws, classes in pairs(workspaceApps) do
    for _, class in ipairs(classes) do
        hl.window_rule({
            name      = "workspace-" .. ws .. "-" .. class,
            match     = { class = class },
            workspace = workspaceSelector[ws],
        })
    end
end

